// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type DrasticChangeProps = Record<string, any>;

const DrasticChange: React.FC<DrasticChangeProps> = ({
  backgroundColor = "#0a0a0a",
  primaryColor = "#FFD700",
  secondaryColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 5,
  textLine1 = "THE CHANGE",
  textLine2 = "WAS DRASTIC",
  gridCols = 5,
  gridRows = 7,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Timing Configuration
  const EXPLOSION_FRAME = 60;
  const isImpact = frame >= EXPLOSION_FRAME && frame < EXPLOSION_FRAME + 3;

  // Parser Safety / Background Logic
  let activeBgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Flash the background during impact frames for "Drastic" effect
  if (!transparentBackground && isImpact) {
    if (frame === EXPLOSION_FRAME) activeBgColor = secondaryColor;
    else if (frame === EXPLOSION_FRAME + 1) activeBgColor = primaryColor;
    else if (frame === EXPLOSION_FRAME + 2) activeBgColor = secondaryColor;
  }

  // Pre-calculate grid data
  const totalGridItems = gridCols * gridRows;
  const gridSpacingX = width * 0.15;
  const gridSpacingY = width * 0.15;
  
  const gridItems = Array.from({ length: totalGridItems }).map((_, i) => {
    const c = i % gridCols;
    const r = Math.floor(i / gridCols);
    const x = (c - (gridCols - 1) / 2) * gridSpacingX;
    const y = (r - (gridRows - 1) / 2) * gridSpacingY;
    const dist = Math.sqrt(x * x + y * y);
    return { id: i, x, y, dist };
  });

  const showGrid = frame < EXPLOSION_FRAME;
  const showHero = frame >= EXPLOSION_FRAME - 5; // Allow slight overlap for continuity

  // Hero Shape Springs (Phase 3: Explosion)
  const heroSpring1 = spring({ frame: frame - EXPLOSION_FRAME, fps, config: { damping: 14, stiffness: 90 } });
  const heroSpring2 = spring({ frame: frame - (EXPLOSION_FRAME + 2), fps, config: { damping: 15, stiffness: 100 } });
  const heroSpring3 = spring({ frame: frame - (EXPLOSION_FRAME + 4), fps, config: { damping: 13, stiffness: 85 } });
  const ringSpring = spring({ frame: frame - EXPLOSION_FRAME, fps, config: { damping: 30, stiffness: 60 } });
  const linesSpring = spring({ frame: frame - (EXPLOSION_FRAME + 3), fps, config: { damping: 16, stiffness: 110 } });

  // Hero Shape 1 (Giant Yellow Circle)
  const hs1Scale = interpolate(heroSpring1, [0, 1], [0, 1]);
  const hs1X = interpolate(heroSpring1, [0, 1], [0, width * 0.15]);
  const hs1Y = interpolate(heroSpring1, [0, 1], [0, -height * 0.08]);

  // Hero Shape 2 (Huge White Triangle)
  const hs2Scale = interpolate(heroSpring2, [0, 1], [0, 1]);
  const hs2X = interpolate(heroSpring2, [0, 1], [0, -width * 0.25]);
  const hs2Y = interpolate(heroSpring2, [0, 1], [0, height * 0.15]);
  const hs2Rot = interpolate(heroSpring2, [0, 1], [-180, 15]);

  // Hero Shape 3 (Yellow Pill)
  const hs3Scale = interpolate(heroSpring3, [0, 1], [0, 1]);
  const hs3X = interpolate(heroSpring3, [0, 1], [0, width * 0.05]);
  const hs3Y = interpolate(heroSpring3, [0, 1], [0, height * 0.32]);
  const hs3Rot = interpolate(heroSpring3, [0, 1], [0, -25]);

  // Hero Shape 4 (Black Cross inside Yellow Circle)
  const hs4Scale = interpolate(heroSpring1, [0, 1], [0, 1]);
  const hs4Rot = interpolate(heroSpring1, [0, 1], [-90, 45]);

  // Hero Shape 5 (Expanding White Ring)
  const ringScale = interpolate(ringSpring, [0, 1], [0, 2.5]);
  const ringOpacity = interpolate(ringSpring, [0, 0.5, 1], [1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Hero Shape 6 (Parallel Graphic Lines)
  const linesX = interpolate(linesSpring, [0, 1], [-width * 1.5, width * 0.1]);

  // Text Overlay Springs
  const textSpring = spring({ frame: frame - (EXPLOSION_FRAME + 10), fps, config: { damping: 14, stiffness: 90 } });
  const textY1 = interpolate(textSpring, [0, 1], [60, 0]);
  const textY2 = interpolate(textSpring, [0, 1], [80, 0]);
  const textOpacity = interpolate(textSpring, [0, 0.5, 1], [0, 1, 1], { extrapolateRight: "clamp" });
  const tracking1 = interpolate(textSpring, [0, 1], [0.5, 0.05]);
  const tracking2 = interpolate(textSpring, [0, 1], [0.3, -0.02]);

  // Subtle post-explosion drift
  const sceneDriftY = frame >= EXPLOSION_FRAME 
    ? interpolate(frame, [EXPLOSION_FRAME, EXPLOSION_FRAME + 90], [0, -40], { extrapolateLeft: 'clamp', extrapolateRight: 'extend' })
    : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: activeBgColor, fontFamily: interFamily }}>
      
      {/* Scene Container with subtle drift after explosion */}
      <div style={{
        position: 'absolute',
        width: '100%',
        height: '100%',
        transform: `translateY(${sceneDriftY}px)`,
        transition: 'none'
      }}>
        
        {/* PHASE 1 & 2: Orderly Grid merging to center */}
        {showGrid && gridItems.map((item, i) => {
          const delay = item.dist * 0.03; 
          
          // Phase 1: pop in
          const appearSpring = spring({
            frame: frame - (i * 0.5),
            fps,
            config: { damping: 12, stiffness: 100 }
          });
          
          // Phase 2: compress to center
          const mergeStart = 20 + delay;
          const mergeProgress = spring({
            frame: frame - mergeStart,
            fps,
            config: { damping: 15, stiffness: 120 }
          });
          
          const floatY = Math.sin((frame + i * 10) / 15) * 12;
          const floatMultiplier = interpolate(mergeProgress, [0, 1], [1, 0]);
          
          const currentX = interpolate(mergeProgress, [0, 1], [item.x, 0]);
          const currentY = interpolate(mergeProgress, [0, 1], [item.y, 0]) + (floatY * floatMultiplier);
          const currentScale = appearSpring * interpolate(mergeProgress, [0, 1], [1, 0]);
          
          return (
            <div key={item.id} style={{
              position: 'absolute',
              width: width * 0.03,
              height: width * 0.03,
              backgroundColor: secondaryColor,
              borderRadius: '50%',
              left: '50%', top: '50%',
              marginLeft: -width * 0.015,
              marginTop: -width * 0.015,
              transform: `translate(${currentX}px, ${currentY}px) scale(${currentScale})`,
              transition: 'none'
            }} />
          );
        })}

        {/* Core Anticipation Dot (Holds tension right before explosion) */}
        {frame >= 35 && frame < EXPLOSION_FRAME && (
          <div style={{
            position: 'absolute',
            width: width * 0.03,
            height: width * 0.03,
            backgroundColor: secondaryColor,
            borderRadius: '50%',
            left: '50%', top: '50%',
            marginLeft: -width * 0.015,
            marginTop: -width * 0.015,
            transform: `scale(${interpolate(
              spring({ frame: frame - 45, fps, config: { damping: 12, stiffness: 140 } }),
              [0, 1], [0, 2]
            )})`,
            transition: 'none'
          }} />
        )}

        {/* PHASE 3: The Drastic Transformation (Hero Shapes) */}
        {showHero && (
          <>
            {/* Shape 5: Expanding Ring */}
            <div style={{
              position: 'absolute',
              width: width * 0.4,
              height: width * 0.4,
              borderRadius: '50%',
              border: `6px solid ${secondaryColor}`,
              left: '50%', top: '50%',
              marginLeft: -width * 0.2,
              marginTop: -width * 0.2,
              opacity: ringOpacity,
              transform: `scale(${ringScale})`,
              transition: 'none'
            }} />

            {/* Shape 6: Parallel Lines */}
            <div style={{
              position: 'absolute',
              left: '50%', top: '50%',
              transform: `translate(${linesX}px, -${height * 0.25}px) rotate(45deg)`,
              display: 'flex',
              flexDirection: 'column',
              gap: width * 0.03,
              transition: 'none'
            }}>
              <div style={{ width: width, height: width * 0.005, backgroundColor: secondaryColor }} />
              <div style={{ width: width, height: width * 0.005, backgroundColor: secondaryColor }} />
              <div style={{ width: width, height: width * 0.005, backgroundColor: secondaryColor }} />
            </div>

            {/* Shape 1: Giant Yellow Circle */}
            <div style={{
              position: 'absolute',
              width: width * 0.75,
              height: width * 0.75,
              borderRadius: '50%',
              backgroundColor: primaryColor,
              left: '50%', top: '50%',
              marginLeft: -width * 0.375,
              marginTop: -width * 0.375,
              transform: `translate(${hs1X}px, ${hs1Y}px) scale(${hs1Scale})`,
              transition: 'none'
            }} />

            {/* Shape 4: Negative Space Black Cross (Inside Yellow Circle) */}
            <div style={{
              position: 'absolute',
              left: '50%', top: '50%',
              transform: `translate(${hs1X}px, ${hs1Y}px) scale(${hs4Scale}) rotate(${hs4Rot}deg)`,
              transition: 'none'
            }}>
              <div style={{
                position: 'absolute',
                width: width * 0.04,
                height: width * 0.45,
                backgroundColor: backgroundColor,
                marginLeft: -width * 0.02,
                marginTop: -width * 0.225,
                transition: 'none'
              }} />
              <div style={{
                position: 'absolute',
                width: width * 0.45,
                height: width * 0.04,
                backgroundColor: backgroundColor,
                marginLeft: -width * 0.225,
                marginTop: -width * 0.02,
                transition: 'none'
              }} />
            </div>

            {/* Shape 2: Huge White Triangle */}
            <div style={{
              position: 'absolute',
              width: width * 0.65,
              height: width * 0.65,
              backgroundColor: secondaryColor,
              clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)',
              left: '50%', top: '50%',
              marginLeft: -width * 0.325,
              marginTop: -width * 0.325,
              transform: `translate(${hs2X}px, ${hs2Y}px) scale(${hs2Scale}) rotate(${hs2Rot}deg)`,
              transition: 'none'
            }} />

            {/* Shape 3: Yellow Pill */}
            <div style={{
              position: 'absolute',
              width: width * 0.55,
              height: width * 0.18,
              backgroundColor: primaryColor,
              borderRadius: width * 0.09,
              left: '50%', top: '50%',
              marginLeft: -width * 0.275,
              marginTop: -width * 0.09,
              transform: `translate(${hs3X}px, ${hs3Y}px) scale(${hs3Scale}) rotate(${hs3Rot}deg)`,
              transition: 'none'
            }} />
          </>
        )}
      </div>

      {/* Typography Overlay (Maintains exact safe zones and strict palette) */}
      <div style={{
        position: 'absolute',
        bottom: '15%',
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 15,
        zIndex: 10,
        pointerEvents: 'none'
      }}>
        <div style={{
          overflow: 'hidden',
          opacity: textOpacity,
          transform: `translateY(${textY1}px)`,
          transition: 'none'
        }}>
          <div style={{
            backgroundColor: primaryColor,
            color: backgroundColor, // strict contrast compliance
            padding: `${width * 0.02}px ${width * 0.06}px`,
            fontSize: width * 0.045,
            fontWeight: 800,
            letterSpacing: `${tracking1}em`,
            textTransform: 'uppercase',
            whiteSpace: 'nowrap',
            transition: 'none'
          }}>
            {textLine1}
          </div>
        </div>

        <div style={{
          overflow: 'hidden',
          opacity: textOpacity,
          transform: `translateY(${textY2}px)`,
          transition: 'none'
        }}>
          <div style={{
            backgroundColor: secondaryColor,
            color: backgroundColor, // strict contrast compliance
            padding: `${width * 0.02}px ${width * 0.08}px`,
            fontSize: width * 0.09,
            fontWeight: 900,
            letterSpacing: `${tracking2}em`,
            textTransform: 'uppercase',
            whiteSpace: 'nowrap',
            transition: 'none'
          }}>
            {textLine2}
          </div>
        </div>
      </div>

    </AbsoluteFill>
  );
};

export default DrasticChange;